1	/*!
2	 * \file inject_fence_proxy.cc
3	 * \brief Inject proxy fences between generic and async proxies (sm90+)
4	 */
5	
6	#include <tvm/ffi/reflection/registry.h>
7	#include <tvm/ir/transform.h>
8	#include <tvm/runtime/logging.h>
9	#include <tvm/tir/analysis.h>
10	#include <tvm/tir/builtin.h>
11	#include <tvm/tir/op.h>
12	#include <tvm/tir/stmt_functor.h>
13	#include <tvm/tir/transform.h>
14	
15	#include <unordered_map>
16	#include <utility>
17	
18	#include "../op/builtin.h"
19	
20	namespace tvm {
21	namespace tl {
22	
23	using namespace tir;
24	using tvm::transform::PassContext;
25	
26	// Tracks what kind of proxy activity a statement performs so we can decide when
27	// to inject fences while traversing the IR.
28	enum class ProxyKind : uint8_t {
29	  kUnknown,
30	  kGeneric,
31	  kAsync,
32	  kMixed,
33	  kNeutral, // Acts as a barrier and resets proxy state (e.g., fence
34	            // instructions)
35	};
36	
37	namespace {
38	
39	inline bool IsAsync(ProxyKind kind) { return kind == ProxyKind::kAsync; }
40	inline bool IsGeneric(ProxyKind kind) { return kind == ProxyKind::kGeneric; }
41	
42	// Merge two proxy kinds to represent the aggregate behaviour of a compound
43	// node.
44	inline ProxyKind CombineProxy(ProxyKind a, ProxyKind b) {
45	  if (a == ProxyKind::kUnknown)
46	    return b;
47	  if (b == ProxyKind::kUnknown)
48	    return a;
49	  if (a == ProxyKind::kNeutral)
50	    return b;
51	  if (b == ProxyKind::kNeutral)
52	    return a;
53	  if (a == b)
54	    return a;
55	  return ProxyKind::kMixed;
56	}
57	
58	// We only need a fence when transitioning from generic operations to async
59	// ones.
60	inline bool NeedsFence(ProxyKind prev, ProxyKind curr) {
61	  if (prev == ProxyKind::kUnknown || curr == ProxyKind::kUnknown)
62	    return false;
63	  if (prev == ProxyKind::kNeutral || curr == ProxyKind::kNeutral)
64	    return false;
65	  if (prev == ProxyKind::kMixed || curr == ProxyKind::kMixed)
66	    return false;
67	  return IsGeneric(prev) && IsAsync(curr);
68	}
69	
70	inline bool IsFenceCall(const CallNode *call) {
71	  return call && call->op.same_as(fence_proxy_async());
72	}
73	
74	// Identify async intrinsics emitted by TileLang or TVM that require a fence
75	// when they follow generic proxies.
76	bool IsAsyncIntrinsic(const CallNode *call) {
77	  if (call == nullptr) {
78	    return false;
79	  }
80	
81	  // TileLang async intrinsics
82	  if (call->op.same_as(tma_load()) || call->op.same_as(tma_load_im2col()) ||
83	      call->op.same_as(tma_store()) || call->op.same_as(tma_store_arrive()) ||
84	      call->op.same_as(tma_store_wait()) ||
85	      call->op.same_as(ptx_cp_async_barrier_noinc()) ||
86	      call->op.same_as(ptx_wgmma_ss()) || call->op.same_as(ptx_wgmma_rs())) {
87	    return true;
88	  }
89	
90	  // PTX async copy intrinsics
91	  if (call->op.same_as(builtin::ptx_cp_async()) ||
92	      call->op.same_as(builtin::ptx_cp_async_barrier()) ||
93	      call->op.same_as(builtin::ptx_cp_async_bulk())) {
94	    return true;
95	  }
96	
97	  // wgmma async intrinsics
98	  if (call->op.same_as(tl_gemm()) || call->op.same_as(tl_gemm_sp())) {
99	    return true;
100	  }
101	
102	  return false;
103	}
104	
105	// Known ops that must be treated as generic proxies (e.g. ldmatrix/stmatrix).
106	bool IsKnownGeneric(const CallNode *call) {
107	  if (call == nullptr) {
108	    return false;
109	  }
110	  return call->op.same_as(ptx_ldmatrix()) || call->op.same_as(ptx_stmatrix()) ||
111	         call->op.same_as(initialize_wgmma_descriptor()) ||
112	         call->op.same_as(initialize_tcgen05_descriptor());
113	}
114	
115	ProxyKind ProxyFromAttrValue(const ObjectRef &value) {
116	  if (const auto *str = value.as<StringImmNode>()) {
117	    if (str->value == "async") {
118	      return ProxyKind::kAsync;
119	    }
120	    if (str->value == "generic") {
121	      return ProxyKind::kGeneric;
122	    }
123	    if (str->value == "neutral") {
124	      return ProxyKind::kNeutral;
125	    }
126	  }
127	  return ProxyKind::kUnknown;
128	}
129	
130	// TMA stores must be followed by the arrive/wait pair. We rewrite them as part
131	// of the pass to guarantee the proper synchronization semantics.
132	class TMAStoreSyncInjector : public StmtExprMutator {
133	public:
134	  static PrimFunc Apply(PrimFunc f) {
135	    if (!f->body.defined()) {
136	      return f;
137	    }
138	    auto injector = TMAStoreSyncInjector();
139	    f.CopyOnWrite()->body = injector(f->body);
140	    return f;
141	  }
142	
143	private:
144	  Stmt operator()(const Stmt &stmt) { return StmtExprMutator::VisitStmt(stmt); }
145	
146	  Stmt VisitStmt_(const EvaluateNode *op) final {
147	    Stmt mutated = StmtExprMutator::VisitStmt_(op);
148	    const auto *node = mutated.as<EvaluateNode>();
149	    if (const auto *call = node->value.as<CallNode>()) {
150	      if (call->op.same_as(tma_store())) {
151	        Array<Stmt> seq;
152	        seq.push_back(mutated);
153	        seq.push_back(
154	            Evaluate(Call(DataType::Handle(), tma_store_arrive(), {})));
155	        seq.push_back(Evaluate(Call(DataType::Handle(), tma_store_wait(), {})));
156	        return SeqStmt(std::move(seq));
157	      }
158	    }
159	    return mutated;
160	  }
161	};
162	
163	// Main pass: track the proxy state while walking the IR and inject fences when
164	// switching from generic to async proxies.
165	class ProxyFenceInjector : public StmtMutator {
166	public:
167	  static PrimFunc Apply(PrimFunc f) {
168	    if (!f->body.defined()) {
169	      return f;
170	    }
171	    ProxyFenceInjector injector;
172	    f.CopyOnWrite()->body = injector.VisitStmt(f->body);
173	    return f;
174	  }
175	
176	private:
177	  Stmt VisitStmt_(const SeqStmtNode *op) final {
178	    Array<Stmt> seq;
179	    seq.reserve(op->seq.size());
180	
181	    ProxyKind sequence_kind = ProxyKind::kUnknown;
182	    ProxyKind prev_kind = ProxyKind::kUnknown;
183	
184	    for (const Stmt &stmt : op->seq) {
185	      Stmt new_stmt = VisitStmt(stmt);
186	      ProxyKind current_kind = GetProxyKind(new_stmt);
187	
188	      if (!seq.empty() && NeedsFence(prev_kind, current_kind)) {
189	        Stmt fence = MakeFenceStmt();
190	        seq.push_back(fence);
191	        prev_kind = GetProxyKind(fence);
192	      }
193	
194	      seq.push_back(new_stmt);
195	      sequence_kind = CombineProxy(sequence_kind, current_kind);
196	      prev_kind = current_kind;
197	    }
198	
199	    Stmt result = seq.size() == 1 ? seq[0] : SeqStmt(std::move(seq));
200	    SetProxyKind(result, sequence_kind);
201	    return result;
202	  }
203	
204	  Stmt VisitStmt_(const EvaluateNode *op) final {
205	    Stmt stmt = StmtMutator::VisitStmt_(op);
206	    const auto *evaluate = stmt.as<EvaluateNode>();
207	    ProxyKind kind = ProxyKind::kGeneric;
208	
209	    if (const auto *call = evaluate->value.as<CallNode>()) {
210	      if (IsFenceCall(call)) {
211	        kind = ProxyKind::kNeutral;
212	      } else if (IsAsyncIntrinsic(call)) {
213	        kind = ProxyKind::kAsync;
214	      } else if (IsKnownGeneric(call)) {
215	        kind = ProxyKind::kGeneric;
216	      } else {
217	        // We can now treat extern as Generic, since gemm and gemm_sp are never
218	        // represented as call_extern nodes. They are call_intrin nodes and will
219	        // be handled by IsAsyncIntrinsic above.
220	        kind = ProxyKind::kGeneric;
221	      }
222	    }
223	
224	    SetProxyKind(stmt, kind);
225	    return stmt;
226	  }
227	
228	  Stmt VisitStmt_(const BufferStoreNode *op) final {
229	    Stmt stmt = StmtMutator::VisitStmt_(op);
230	    SetProxyKind(stmt, ProxyKind::kGeneric);
231	    return stmt;
232	  }
233	
234	  Stmt VisitStmt_(const IfThenElseNode *op) final {
235	    Stmt stmt = StmtMutator::VisitStmt_(op);
236	    const auto *node = stmt.as<IfThenElseNode>();
237	    ProxyKind kind = GetProxyKind(node->then_case);
238	    if (node->else_case.defined()) {
239	      kind = CombineProxy(kind, GetProxyKind(node->else_case.value()));
240	    }
241	    SetProxyKind(stmt, kind);
242	    return stmt;
243	  }
244	
245	  Stmt VisitStmt_(const AttrStmtNode *op) final {
246	    Stmt stmt = StmtMutator::VisitStmt_(op);
247	    const auto *node = stmt.as<AttrStmtNode>();
248	    ProxyKind body_kind = GetProxyKind(node->body);
249	    SetProxyKind(stmt, body_kind);
250	    return stmt;
251	  }
252	
253	  Stmt VisitStmt_(const BlockRealizeNode *op) final {
254	    Stmt stmt = StmtMutator::VisitStmt_(op);
255	    const auto *node = stmt.as<BlockRealizeNode>();
256	    SetProxyKind(stmt, GetProxyKind(node->block));
257	    return stmt;
258	  }
259	
260	  Stmt VisitStmt_(const BlockNode *op) final {
261	    Stmt stmt = StmtMutator::VisitStmt_(op);
262	    const auto *node = stmt.as<BlockNode>();
263	    ProxyKind kind = ProxyKind::kUnknown;
264	    if (node->init.defined()) {
265	      kind = CombineProxy(kind, GetProxyKind(node->init.value()));
266	    }
267	    kind = CombineProxy(kind, GetProxyKind(node->body));
268	    SetProxyKind(stmt, kind);
269	    return stmt;
270	  }
271	
272	  Stmt VisitStmt_(const ForNode *op) final { return VisitSingleBody(op); }
273	  Stmt VisitStmt_(const LetStmtNode *op) final { return VisitSingleBody(op); }
274	  Stmt VisitStmt_(const AssertStmtNode *op) final {
275	    return VisitSingleBody(op);
276	  }
277	  Stmt VisitStmt_(const WhileNode *op) final { return VisitSingleBody(op); }
278	
279	  template <typename NodeType> Stmt VisitSingleBody(const NodeType *op) {
280	    Stmt stmt = StmtMutator::VisitStmt_(op);
281	    const auto *node = stmt.as<NodeType>();
282	    ProxyKind body_kind = GetProxyKind(node->body);
283	    SetProxyKind(stmt, body_kind);
284	    return stmt;
285	  }
286	
287	  void SetProxyKind(const Stmt &stmt, ProxyKind kind) {
288	    proxy_map_[stmt.get()] = kind;
289	  }
290	
291	  ProxyKind GetProxyKind(const Stmt &stmt) const {
292	    if (!stmt.defined()) {
293	      return ProxyKind::kUnknown;
294	    }
295	    auto it = proxy_map_.find(stmt.get());
296	    if (it == proxy_map_.end()) {
297	      return ProxyKind::kUnknown;
298	    }
299	    return it->second;
300	  }
301	
302	  Stmt MakeFenceStmt() {
303	    Stmt fence = Evaluate(Call(DataType::Handle(), fence_proxy_async(), {}));
304	    SetProxyKind(fence, ProxyKind::kNeutral);
305	    return fence;
306	  }
307	
308	  std::unordered_map<const StmtNode *, ProxyKind> proxy_map_;
309	};
310	
311	} // namespace
