313	tvm::transform::Pass InjectFenceProxy() {
314	  auto pass_func = [](PrimFunc f, const IRModule &, const PassContext &) {
315	    f = TMAStoreSyncInjector::Apply(f);
316	    f = ProxyFenceInjector::Apply(f);
317	    return f;
318	  };
319	  return tir::transform::CreatePrimFuncPass(pass_func, 0, "tl.InjectFenceProxy",
320	                                            {});
321	}
322	
