47	/*!
48	 * \brief collect the mapping from the buffer var to its allocate
49	 */
50	class AllocateCollector : public StmtExprVisitor {
51	
52	private:
53	  bool IsDynamicSharedMemory(Var buffer_var) {
54	    StorageScope storage_scope = runtime::StorageScope::Create(
55	        GetPtrStorageScope(std::move(buffer_var)));
56	    return storage_scope.rank == runtime::StorageRank::kShared &&
57	           storage_scope.tag == ".dyn";
58	  }
59	
60	  bool IsStaticSharedMemory(Var buffer_var) {
61	    StorageScope storage_scope = runtime::StorageScope::Create(
62	        GetPtrStorageScope(std::move(buffer_var)));
63	    return storage_scope.rank == runtime::StorageRank::kShared &&
64	           storage_scope.tag.empty();
65	  }
66	
67	public:
68	  void VisitStmt_(const AllocateNode *op) final {
69	    if (IsDynamicSharedMemory(op->buffer_var)) {
70	      dyn_shmem_allocs_[op->buffer_var.get()] = op;
71	    } else if (IsStaticSharedMemory(op->buffer_var)) {
72	      static_shmem_allocs_[op->buffer_var.get()] = op;
73	    }
74	    StmtExprVisitor::VisitStmt_(op);
75	  }
76	  // The dynamic mapping from the original buffer var to its allocate
77	  std::unordered_map<const VarNode *, const AllocateNode *> dyn_shmem_allocs_;
78	  // The static mapping from the original buffer var to its allocate
79	  std::unordered_map<const VarNode *, const AllocateNode *>
80	      static_shmem_allocs_;
81	};
82	
83	class ThreadAllreduceBuilder final : public StmtExprMutator {
84	public:
85	  explicit ThreadAllreduceBuilder(const TargetNode *target,
86	                                  bool is_dynamic = false)
87	      : target_(target),
88	        warp_size_(
89	            target->GetAttr<Integer>("thread_warp_size", 1).value().IntValue()),
90	        max_num_threads_(target->GetAttr<Integer>("max_num_threads", -1)
91	                             .value()
92	                             .IntValue()) {
93	    if (is_dynamic) {
94	      shared_scope = "shared.dyn";
95	    }
96	  }
97	
98	  Stmt VisitStmt_(const AttrStmtNode *op) final {
99	    if (op->attr_key == tir::attr::thread_extent) {
100	      thread_extents_.push_back(op);
101	      Stmt ret = StmtExprMutator::VisitStmt_(op);
102	      thread_extents_.pop_back();
103	      return ret;
104	    } else if (op->attr_key == tir::attr::reduce_scope) {
105	      const CommReducerNode *combiner = op->node.as<CommReducerNode>();
106	      ICHECK(combiner);
107	      reduce_combiner_.push_back(combiner);
108	      Stmt ret = StmtExprMutator::VisitStmt_(op);
109	      reduce_combiner_.pop_back();
110	      return ret;
111	    } else {
112	      return StmtExprMutator::VisitStmt_(op);
113	    }
114	  }
115	  Stmt VisitStmt_(const EvaluateNode *op) final {
116	    Stmt stmt = StmtExprMutator::VisitStmt_(op);
117	    op = stmt.as<EvaluateNode>();
118	    const CallNode *call = op->value.as<CallNode>();
119	    if (call && call->op.same_as(builtin::tvm_thread_allreduce())) {
120	      return MakeAllreduce(call);
121	    } else {
122	      return stmt;
123	    }
124	  }
125	  Stmt VisitStmt_(const AllocateNode *op) final {
126	    auto node = Downcast<Allocate>(StmtExprMutator::VisitStmt_(op));
127	
128	    if (auto it = alloc_remap_.find(node->buffer_var.get());
129	        it != alloc_remap_.end()) {
130	      Buffer buf = Downcast<Buffer>(it->second);
131	      auto write_ptr = node.CopyOnWrite();
132	      write_ptr->buffer_var = buf->data;
133	      write_ptr->dtype = buf->dtype;
134	      write_ptr->extents = buf->shape;
135	      write_ptr->condition = const_true(buf->dtype.lanes());
136	
137	      if (buf.scope() == shared_scope) {
138	        // Use volatile access to shared buffer.
139	        write_ptr->body =
140	            AttrStmt(buf->data, tir::attr::volatile_scope, 1, write_ptr->body);
141	      }
142	    }
143	    return std::move(node);
144	  }
145	
146	  Optional<Buffer> GetRemappedBuffer(const Buffer &buf) {
147	    if (auto it = buf_remap_.find(buf.get()); it != buf_remap_.end()) {
148	      return it->second;
149	    }
150	
151	    if (auto it = var_remap_.find(buf->data.get()); it != var_remap_.end()) {
152	      Buffer new_buf = buf;
153	      new_buf.CopyOnWrite()->data = it->second;
154	      buf_remap_[buf.get()] = new_buf;
155	      return new_buf;
156	    }
157	
158	    return std::nullopt;
159	  }
160	
161	  Stmt VisitStmt_(const DeclBufferNode *op) final {
162	    auto node = Downcast<DeclBuffer>(StmtExprMutator::VisitStmt_(op));
163	    if (auto buf = GetRemappedBuffer(node->buffer)) {
164	      node.CopyOnWrite()->buffer = buf.value();
165	    }
166	    return std::move(node);
167	  }
168	
169	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
170	    if (auto it = load_remap_.find(op->buffer->data.get());
171	        it != load_remap_.end()) {
172	      for (const auto &index : op->indices) {
173	        ICHECK(is_zero(index))
174	            << "The index of buffer " << op->buffer << " is " << index;
175	      }
176	      return it->second;
177	    }
178	
179	    BufferLoad load = Downcast<BufferLoad>(StmtExprMutator::VisitExpr_(op));
180	
181	    if (auto opt = GetRemappedBuffer(load->buffer)) {
182	      load.CopyOnWrite()->buffer = opt.value();
183	    }
184	    return std::move(load);
185	  }
186	
187	  Stmt VisitStmt_(const BufferStoreNode *op) final {
188	    BufferStore store = Downcast<BufferStore>(StmtExprMutator::VisitStmt_(op));
189	
190	    if (auto opt = GetRemappedBuffer(store->buffer)) {
191	      store.CopyOnWrite()->buffer = opt.value();
192	    }
193	    return std::move(store);
194	  }
195	
196	private:
197	  // Thread entry
198	  struct ThreadEntry {
199	    runtime::ThreadScope scope;
200	    IterVar iv;
201	    int extent{};
202	    // comparator
203	    bool operator<(const ThreadEntry &other) const {
204	      return scope.dim_index < other.scope.dim_index;
205	    }
206	  };
207	
208	  // make allreduce.
209	  Stmt MakeAllreduce(const CallNode *call) {
210	    ICHECK(!reduce_combiner_.empty());
211	    const CommReducerNode *combiner = reduce_combiner_.back();
212	    size_t size = combiner->result.size();
213	
214	    const IntImmNode *size_of_args = call->args[0].as<IntImmNode>();
215	    ICHECK(size_of_args) << call->args[0]->GetTypeKey();
216	    ICHECK_EQ(size, size_of_args->value);
217	    Array<PrimExpr> inits = combiner->identity_element;
218	    std::vector<PrimExpr> values(size);
219	    std::vector<DataType> types(size);
220	    PrimExpr cond = call->args[size + 1];
221	    for (size_t idx = 0; idx < size; ++idx) {
222	      values[idx] = call->args[1 + idx];
223	      if (!is_one(cond)) {
224	        values[idx] = Select(cond, values[idx], inits[idx]);
225	      }
226	      types[idx] = values[idx].dtype();
227	    }
228	    std::vector<Buffer> buffers(size);
229	    for (size_t idx = 0; idx < size; ++idx) {
230	      PrimExpr arg = call->args[2 + size + idx];
231	      // Loads from boolean buffers may have cast nodes inserted by
232	      // earlier passes.
233	      if (auto cast = arg.as<CastNode>()) {
234	        arg = cast->value;
235	      }
236	      buffers[idx] = Downcast<BufferLoad>(arg)->buffer;
237	    }
238	
239	    std::unordered_set<const VarNode *> reduce_set;
240	    for (size_t i = 2 + 2 * size; i < call->args.size(); ++i) {
241	      const VarNode *v = call->args[i].as<VarNode>();
242	      // The simply optimization replace a iteration variable with a constant
243	      // when extent of the iteration is 1. As threaded IterVar always started
244	      // from 0, we can just ignore this variable in this case.
245	      if (v) {
246	        reduce_set.insert(v);
247	      } else {
248	        ICHECK(call->args[i].as<IntImmNode>() &&
249	               call->args[i].as<IntImmNode>()->value == 0)
250	            << "arg" << i << "should be a VarNode or IntImmNode "
251	            << "while it is " << call->args[i];
252	      }
253	    }
254	
255	    size_t nmatch = 0;
256	    std::vector<ThreadEntry> vred, vpar;
257	    int reduce_dim_index = -1;
258	    for (const AttrStmtNode *attr : thread_extents_) {
259	      ThreadEntry e;
260	      IterVar iv = Downcast<IterVar>(attr->node);
261	      e.scope = runtime::ThreadScope::Create(iv->thread_tag);
262	      e.iv = iv;
263	      ICHECK_LE(e.scope.rank, 1);
264	      ICHECK_GE(e.scope.dim_index, 0)
265	          << "vthread do not work with cross thread reduction";
266	      if (e.scope.rank == 1) {
267	        const auto *ptr = attr->value.as<IntImmNode>();
268	        ICHECK(ptr) << "Need constant extent for reduce set " << iv;
269	        e.extent = static_cast<int>(ptr->value);
270	        // ignore variables equal to 0
271	        if (e.extent == 1) {
272	          continue;
273	        }
274	
275	        if (reduce_set.count(iv->var.get())) {
276	          bool already_exists = false;
277	          for (const auto &entry : vred) {
278	            if (entry.scope.dim_index == e.scope.dim_index) {
279	              already_exists = true;
280	              break;
281	            }
282	          }
283	          if (!already_exists) {
284	            vred.push_back(e);
285	            ++nmatch;
286	            reduce_dim_index = e.scope.dim_index;
287	          }
288	        } else {
289	          bool already_exists = false;
290	          for (const auto &entry : vpar) {
291	            if (entry.scope.dim_index == e.scope.dim_index) {
292	              already_exists = true;
293	              break;
294	            }
295	          }
296	          if (!already_exists) {
297	            vpar.push_back(e);
298	          }
299	        }
300	      }
301	    }
302	
303	    // remove reduce thread from parallel thread
304	    if (reduce_dim_index != -1) {
305	      for (size_t i = 0; i < vpar.size(); ++i) {
306	        if (vpar[i].scope.dim_index == reduce_dim_index) {
307	          vpar.erase(vpar.begin() + i);
308	          break;
309	        }
310	      }
311	    }
312	
313	    ICHECK_EQ(nmatch, reduce_set.size())
314	        << "Not all reduce index are presented in the context";
315	    std::sort(vred.begin(), vred.end());
316	    std::sort(vpar.begin(), vpar.end());
317	    // the size of each index.
318	    int reduce_extent, group_extent;
319	    PrimExpr reduce_index = FlattenThread(vred, &reduce_extent);
320	    PrimExpr group_index = FlattenThread(vpar, &group_extent);
321	
322	    // the longest contiguous reduce extent after flattening
323	    int contiguous_reduce_extent = 1;
324	    std::vector<std::tuple<int, int, bool>>
325	        block_threads; // tuple(dim_index, extent, is_reduce)
326	    for (const ThreadEntry &thr : vred) {
327	      if (thr.scope.rank == 1) { // threadIdx
328	        block_threads.emplace_back(thr.scope.dim_index, thr.extent, true);
329	      }
330	    }
331	    for (const ThreadEntry &thr : vpar) {
332	      if (thr.scope.rank == 1) { // threadIdx
333	        block_threads.emplace_back(thr.scope.dim_index, thr.extent, false);
334	      }
335	    }
336	    // sort according to dim_index
337	    std::sort(block_threads.begin(), block_threads.end());
338	    for (auto &&thr_attr : block_threads) {
339	      auto [dim_index, extent, is_reduce] = thr_attr;
340	      (void)dim_index; // https://gcc.gnu.org/bugzilla/show_bug.cgi?id=81767
341	      if (is_reduce) {
342	        contiguous_reduce_extent *= extent;
343	      } else {
344	        break;
345	      }
346	    }
347	
348	    std::vector<Stmt> seq;
349	    std::vector<Buffer> new_alloc_bufs;
350	    //
351	    // This is an optimization. For small reduction sizes, it may be beneficial
352	    // for a single warp to performance the entire reduction. No trips to shared
353	    // memory and no cross warp synchronizations are required.
354	    // The following code emits the reduction as follows:
355	    //
356	    // Allocate reduction vars v[i], i = 0..size-1
357	    //
358	    // for offset from WARP_SIZE to 1 by 2
359	    //
360	    //   a    <- load(v[i])
361	    //   b    <- shuffle_down(load(v[i], offset))
362	    //   v[i] <- reduction(a, b)
363	    //
364	    // broadcast results from lane 0 to all other lanes and store
365	    // the final reduction result to the proper location.
366	    //
367	    // When the thread extent is multiple of warp size, we can use a two-stage
368	    // warp-level reduction to optimize. This is implemented by applying the
369	    // algorithm above twice.
370	    //
371	    // For example, suppose we want to use 512 threads to reduce 512 elements
372	    // and the warp size is 32. In this case there are (512 / 32) = 16 warps.
373	    // In the first stage, each of the 16 warps reduces 32 elements. So after
374	    // the stage, we have 16 remaining elements to be reduced, one for each
375	    // warp. We store the 16 elements in shared memory, and start the second
376	    // stage. In the second stage we use the first 16 lanes of the first warp to
377	    // reduce the remaining elements, and this reduction can also be optimized
378	    // by shuffle_down warp-level primitives.
379	    PrimExpr zero_index = make_const(reduce_index->dtype, 0);
380	
381	    if (IsWarpReduction(types, group_extent, reduce_extent,
382	                        contiguous_reduce_extent)) {
383	      std::vector<PrimExpr> reduce_results;
384	      DataType mask_dtype = DataType::UInt(32);
385	      PrimExpr mask = Call(mask_dtype, builtin::tvm_warp_activemask(), {});
386	
387	      if (reduce_extent <= warp_size_) {
388	        std::tie(reduce_results, new_alloc_bufs) = MakeWarpAllreduce(
389	            values, types, combiner, reduce_index, reduce_extent, group_index,
390	            mask, std::nullopt, &seq);
391	
392	        // Broadcast the reduction result from lane 0 to all other lanes.
393	        // This avoids to emit predicated stores, as all threads are
394	        // uniformly writing the same result.
395	        for (size_t i = 0; i < size; ++i) {
396	          Buffer buf = Downcast<BufferLoad>(reduce_results[i])->buffer;
397	          PrimExpr val = BufferLoad(buf, {zero_index});
398	          ICHECK_EQ(val->dtype, types[i]);
399	          PrimExpr splat =
400	              WarpShuffle(builtin::tvm_warp_shuffle(), new_alloc_bufs.back(),
401	                          val, reduce_extent * group_index);
402	          seq.push_back(BufferStore(buf, splat, {zero_index}));
403	        }
404	      } else {
405	        int n_warps = reduce_extent / warp_size_;
406	        std::vector<Buffer> local_bufs;
407	
408	        // 1. Create the staging buffer in shared memory.
409	        std::vector<Buffer> staging_shared_bufs;
410	        staging_shared_bufs.reserve(size);
411	        for (size_t i = 0; i < size; ++i) {
412	          Buffer staging_shared_buf = decl_buffer(
413	              /*shape=*/{make_const(reduce_index->dtype,
414	                                    n_warps * group_extent)},
415	              /*dtype=*/buffers[i]->dtype, /*name=*/"red_buf_staging",
416	              /*storage_scope=*/shared_scope);
417	          staging_shared_bufs.push_back(staging_shared_buf);
418	          new_alloc_bufs.push_back(staging_shared_buf);
419	        }
420	
421	        // 2. First round of allreduce.
422	        std::tie(reduce_results, local_bufs) =
423	            MakeWarpAllreduce(values, types, combiner, reduce_index, warp_size_,
424	                              group_index, mask, std::nullopt, &seq);
425	        new_alloc_bufs.insert(new_alloc_bufs.end(), local_bufs.begin(),
426	                              local_bufs.end());
427	
428	        // 3. Write allreduce results to staging buffer.
429	        std::vector<Stmt> write_staging_buf;
430	        write_staging_buf.reserve(size);
431	        for (size_t i = 0; i < size; ++i) {
432	          new_alloc_bufs.push_back(
433	              Downcast<BufferLoad>(reduce_results[i])->buffer);
434	          write_staging_buf.push_back(BufferStore(
435	              /*buffer=*/staging_shared_bufs[i],
436	              /*value=*/reduce_results[i],
437	              /*indices=*/
438	              {group_index * n_warps + floordiv(reduce_index, warp_size_)}));
439	        }
440	        PrimExpr cond = floormod(reduce_index, warp_size_) == zero_index;
441	        seq.push_back(IfThenElse(cond, SeqStmt::Flatten(write_staging_buf)));
442	        seq.push_back(SyncThread(shared_scope));
443	
444	        // 4. Load staging buffer.
445	        //    Second round of allreduce.
446	        for (size_t i = 0; i < size; ++i) {
447	          values[i] =
448	              BufferLoad(/*buffer=*/staging_shared_bufs[i],
449	                         /*indices=*/{group_index * n_warps + reduce_index});
450	        }
451	        std::tie(reduce_results, local_bufs) = MakeWarpAllreduce(
452	            values, types, combiner, reduce_index, n_warps, group_index, mask,
453	            /*predicate=*/reduce_index <
454	                make_const(reduce_index->dtype, n_warps),
455	            &seq);
456	        new_alloc_bufs.insert(new_alloc_bufs.end(), local_bufs.begin(),
457	                              local_bufs.end());
458	
459	        // 5. Create shared memory buffer(s) of `group_extent` elements, storing
460	        // the allreduce results so each thread can access.
461	        std::vector<Stmt> write_result;
462	        write_result.reserve(size);
463	        for (size_t i = 0; i < size; ++i) {
464	          new_alloc_bufs.push_back(
465	              Downcast<BufferLoad>(reduce_results[i])->buffer);
466	          Buffer broadcast_shared_buf = decl_buffer(
467	              /*shape=*/{make_const(reduce_index->dtype, group_extent)},
468	              /*dtype=*/buffers[i]->dtype, /*name=*/"red_result",
469	              /*storage_scope=*/shared_scope);
470	          write_result.push_back(BufferStore(broadcast_shared_buf,
471	                                             reduce_results[i], {group_index}));
472	          // Update `reduce_results`, pointing to the value loaded from the
473	          // shared memory buffer.
474	          reduce_results[i] = BufferLoad(broadcast_shared_buf, {group_index});
475	        }
476	        seq.push_back(IfThenElse(reduce_index == zero_index,
477	                                 SeqStmt::Flatten(write_result)));
478	        seq.push_back(SyncThread(shared_scope));
479	      }
480	
481	      // Write back allreduce results and update existing allocations.
482	      for (size_t i = 0; i < size; ++i) {
483	        ICHECK(!load_remap_.count(buffers[i]->data.get()));
484	        PrimExpr pred = const_true(types[i].lanes());
485	        Buffer buf = Downcast<BufferLoad>(reduce_results[i])->buffer;
486	        ICHECK_EQ(reduce_results[i]->dtype, types[i]);
487	        load_remap_[buffers[i]->data.get()] = reduce_results[i];
488	
489	        auto node =
490	            Allocate(buf->data, types[i], buf->shape, pred, Evaluate(0));
491	        alloc_remap_[buffers[i]->data.get()] = buf;
492	        var_remap_[buffers[i]->data.get()] = buf->data;
493	        buf_remap_[buffers[i].get()] = buf;
494	      }
495	    } else {
496	      std::vector<Buffer> shared_bufs(size);
497	      if (reduce_extent == 1) {
498	        // special case, no reduction is needed.
499	        std::vector<Stmt> stores;
500	        stores.reserve(size);
501	        for (size_t i = 0; i < size; ++i) {
502	          stores.emplace_back(BufferStore(buffers[i], values[i], {0}));
503	        }
504	        return SeqStmt::Flatten(stores);
505	      }
506	      // This sync is necessary because there might be incomplete read of
507	      // previous iteration on the same buffer.
508	      seq.emplace_back(SyncThread(shared_scope));
509	      for (size_t idx = 0; idx < size; ++idx) {
510	        shared_bufs[idx] = decl_buffer(
511	            {IntImm(group_index->dtype, group_extent * reduce_extent)},
512	            types[idx], "red_buf" + std::to_string(idx), shared_scope);
513	        seq.emplace_back(
514	            BufferStore(shared_bufs[idx], values[idx],
515	                        {BufIndex(reduce_index, group_index, reduce_extent)}));
516	      }
517	      seq.emplace_back(SyncThread(shared_scope));
518	      seq.emplace_back(MakeBufAllreduce(
519	          combiner, types, shared_bufs, reduce_index, group_index,
520	          reduce_extent, group_extent, contiguous_reduce_extent));
521	      for (size_t idx = 0; idx < size; ++idx) {
522	        ICHECK(!load_remap_.count(buffers[idx]->data.get()));
523	        PrimExpr pred = const_true(types[idx].lanes());
524	        BufferLoad load(shared_bufs[idx],
525	                        {BufIndex(make_zero(reduce_index.dtype()), group_index,
526	                                  reduce_extent)});
527	        ICHECK_EQ(load->dtype, types[idx]);
528	        load_remap_[buffers[idx]->data.get()] = load;
529	        alloc_remap_[buffers[idx]->data.get()] = shared_bufs[idx];
530	        var_remap_[buffers[idx]->data.get()] = shared_bufs[idx]->data;
531	        buf_remap_[buffers[idx].get()] = shared_bufs[idx];
532	      }
533	    }
534	
535	    // Fix all local allocations as all statements are built.
536	    Stmt body = SeqStmt::Flatten(seq);
537	    for (const Buffer &buf : new_alloc_bufs) {
538	      body = DeclBuffer(buf, body);
539	      body = Allocate(buf->data, buf->dtype, buf->shape,
540	                      const_true(buf->dtype.lanes()), body);
541	    }
542	
543	    return body;
544	  }
545	
546	  std::pair<std::vector<PrimExpr>, std::vector<Buffer>>
547	  MakeWarpAllreduce(std::vector<PrimExpr> src_values,                //
548	                    std::vector<DataType> dtypes,                    //
549	                    const CommReducerNode *combiner,                 //
550	                    const PrimExpr &reduce_index, int reduce_extent, //
551	                    const PrimExpr &group_index,                     //
552	                    const PrimExpr &mask,
553	                    const Optional<PrimExpr> &predicate, //
554	                    std::vector<Stmt> *seq) {
555	    int n_buffers = src_values.size();
556	
557	    std::vector<Buffer> shared_bufs;
558	    std::vector<Buffer> local_bufs;
559	    shared_bufs.reserve(n_buffers);
560	
561	    // This is the index to the reduction variable, one reduction
562	    // variable per warp. Local scope seems easier to reason without
563	    // relying on a pattern match pass to fix it later.
564	    Array<PrimExpr> zero_indices = {0};
565	    Array<PrimExpr> shape = {1};
566	
567	    std::vector<Stmt> load_values;
568	    load_values.reserve(n_buffers);
569	    for (int idx = 0; idx < n_buffers; ++idx) {
570	      shared_bufs.push_back(decl_buffer(
571	          shape, dtypes[idx], "red_buf" + std::to_string(idx), "local"));
572	      load_values.push_back(
573	          BufferStore(shared_bufs[idx], src_values[idx], zero_indices));
574	
575	      // Uses a local variable to store the shuffled data.  Later
576	      // on, an allocation will be built for this local variable.
577	      local_bufs.push_back(
578	          decl_buffer(shape, dtypes[idx], "t" + std::to_string(idx), "local"));
579	    }
580	
581	    if (predicate.defined()) {
582	      seq->push_back(
583	          IfThenElse(predicate.value(), SeqStmt::Flatten(load_values)));
584	    } else {
585	      seq->insert(seq->end(), load_values.begin(), load_values.end());
586	    }
587	
588	    // The mask for this reducer, as this reducer may sit inside
589	    // a divergent control flow. Here it uses a variable to cache the current
590	    // active channels.
591	    Optional<Buffer> mask_buffer;
592	    if (need_warp_shuffle_mask_) {
593	      mask_buffer = decl_buffer(shape, mask->dtype, "mask", "local");
594	      seq->emplace_back(BufferStore(mask_buffer.value(), mask, zero_indices));
595	      // Push the buffer description.  Later this will have an
596	      // allocation built for it.
597	      local_bufs.push_back(mask_buffer.value());
598	    }
599	
600	    // Emit reductions within a warp.
601	    int start_offset = 1;
602	    while (start_offset * 2 < reduce_extent) {
603	      start_offset *= 2;
604	    }
605	    for (int offset = start_offset; offset > 0; offset /= 2) {
606	      // Load reduction values, no synchronization needed.
607	      Array<PrimExpr> a, b;
608	      for (int i = 0; i < n_buffers; ++i) {
609	        const Buffer &shared_buf = shared_bufs[i];
610	        BufferLoad val(shared_buf, zero_indices);
611	        ICHECK_EQ(val->dtype, dtypes[i]);
612	        a.push_back(val);
613	
614	        // __shfl_*sync calls shall not appear in if_then_else expressions
615	        // as this is causing extra divergency. E.g.
616	        //
617	        // v1 = (v2 < v3) ? v3 : __shfl_sync(mask, v1, 0);
618	        //
619	        // behaves differently from
620	        //
621	        // int t = __shfl_sync(mask, v1, 0);
622	        // v1 = (v2 < v3) ? v3 : t;
623	        //
624	        // The former may cause dead lock as there is a divergent
625	        // branch with a warp sync call inside.
626	        PrimExpr other = WarpShuffle(builtin::tvm_warp_shuffle_down(),
627	                                     mask_buffer, val, offset);
628	        const Buffer &local_buf = local_bufs[i];
629	        Stmt s = BufferStore(local_buf, other, zero_indices);
630	        seq->push_back(s);
631	
632	        BufferLoad load = BufferLoad(local_buf, zero_indices);
633	        ICHECK_EQ(load->dtype, dtypes[i]);
634	        b.push_back(load);
635	      }
636	
637	      // Do reductions.
638	      Array<PrimExpr> ret = (*combiner)(a, b);
639	
640	      // Store the reduction result to itself.
641	      std::vector<Stmt> stores;
642	      stores.reserve(n_buffers);
643	      for (int i = 0; i < n_buffers; ++i) {
644	        const Buffer &buf = shared_bufs[i];
645	        stores.push_back(BufferStore(buf, ret[i], zero_indices));
646	      }
647	
648	      // During the sub-warp reduction, values from inactive threads could be
649	      // read, which is an undefined behavior according to the cuda document.
650	      //
651	      // In practice, the return value are usually 0, which does no harm to sum
652	      // reduction. However, the result can be incorrect in max or prod
653	      // reduction. Therefore an additional range check has to be performed to
654	      // ensure the correctness.
655	      if (offset * 2 > reduce_extent) {
656	        PrimExpr cond = reduce_index + offset < reduce_extent;
657	        seq->push_back(IfThenElse(cond, SeqStmt::Flatten(stores)));
658	      } else {
659	        seq->push_back(SeqStmt::Flatten(stores));
660	      }
661	    }
662	
663	    std::vector<PrimExpr> reduce_results;
664	    reduce_results.reserve(n_buffers);
665	    for (int i = 0; i < n_buffers; ++i) {
666	      reduce_results.push_back(BufferLoad(shared_bufs[i], zero_indices));
667	    }
668	
669	    return {reduce_results, local_bufs};
670	  }
671	
672	  // make allreduce.
673	  Stmt MakeBufAllreduce(const CommReducerNode *combiner,
674	                        const std::vector<DataType> &types,
675	                        const Array<Buffer> &shared_bufs, PrimExpr reduce_index,
676	                        PrimExpr group_index, int reduce_extent,
677	                        int group_extent, int contiguous_reduce_extent) {
678	    // Get next power of two
679	    int reduce_align = 1;
680	    while (reduce_extent > reduce_align) {
681	      reduce_align = reduce_align << 1;
682	    }
683	    ICHECK_GT(reduce_align, 1);
684	    std::vector<Stmt> seq;
685	
686	    size_t size = shared_bufs.size();
687	    PrimExpr buf_index = BufIndex(reduce_index, group_index, reduce_extent);
688	    // make reduction
689	    auto fload = [&](int offset) {
690	      Array<PrimExpr> a, b;
691	      for (size_t i = 0; i < size; ++i) {
692	        BufferLoad b_load(
693	            shared_bufs[i],
694	            {BufIndex(reduce_index + offset, group_index, reduce_extent)});
695	        ICHECK_EQ(b_load->dtype, types[i]);
696	        b.push_back(b_load);
697	
698	        BufferLoad a_load(shared_bufs[i], {buf_index});
699	        ICHECK_EQ(a_load->dtype, types[i]);
700	        a.push_back(a_load);
701	      }
702	      Array<PrimExpr> ret = (*combiner)(a, b);
703	      return ret;
704	    };
705	    auto fstore = [&](const Array<PrimExpr> &ret) {
706	      std::vector<Stmt> stores(size);
707	      for (size_t i = 0; i < size; ++i) {
708	        stores[i] = BufferStore(shared_bufs[i], ret[i], {buf_index});
709	      }
710	      return SeqStmt::Flatten(stores);
711	    };
712	    auto freduce = [&](int offset) {
713	      auto ret = fload(offset);
714	      return fstore(ret);
715	    };
716	    // Step one, check for
717	    if (reduce_align > reduce_extent) {
718	      // reduction with the boundary condition
719	      reduce_align = reduce_align >> 1;
720	      PrimExpr cond = reduce_index < (reduce_extent - reduce_align);
721	      seq.emplace_back(IfThenElse(cond, freduce(reduce_align)));
722	      seq.emplace_back(SyncThread(shared_scope));
723	    }
724	
725	    // normal synchronization
726	    bool warp_align =
727	        group_extent == 1 || contiguous_reduce_extent % warp_size_ == 0;
728	    while (reduce_align > contiguous_reduce_extent ||
729	           reduce_align > warp_size_ || !warp_align) {
730	      if (reduce_align == 1) {
731	        break;
732	      }
733	      reduce_align = reduce_align >> 1;
734	      PrimExpr cond = reduce_index < reduce_align;
735	      seq.emplace_back(IfThenElse(cond, freduce(reduce_align)));
736	      seq.emplace_back(SyncThread(shared_scope));
737	    }
738	    // in warp synchronization.
739	    if (reduce_align > 1) {
740	      PrimExpr in_warp_cond = reduce_index < (reduce_align >> 1);
741	
742	      std::vector<Stmt> in_warp_seq;
743	
744	      while (reduce_align > 1) {
745	        reduce_align = reduce_align >> 1;
746	
747	        // freduce can read/write to the same memory location.  For
748	        // example, with reduce_align of 4, threadIdx 3 reads from
749	        // memory location 7 as threadIdx 7 is writing to it.
750	        // Therefore, we need to separate out the load from the store
751	        // with a memory barrier in-between.  This isn't necessary for
752	        // the earlier normal synchronization, because those are each
753	        // protected by an if-statement.  The if-statement is avoided
754	        // here to reduce thread divergence.
755	        auto loads = fload(reduce_align);
756	
757	        Array<Var> in_warp_local_vars;
758	        for (auto expr : loads) {
759	          Var var("w_" + std::to_string(reduce_align) + "_" +
760	                      std::to_string(in_warp_local_vars.size()),
761	                  expr->dtype);
762	          in_warp_local_vars.push_back(var);
763	        }
764	
765	        std::vector<Stmt> in_let_statement;
766	        in_let_statement.emplace_back(SyncThread("warp"));
767	        in_let_statement.emplace_back(
768	            fstore({in_warp_local_vars.begin(), in_warp_local_vars.end()}));
769	        in_let_statement.emplace_back(SyncThread("warp"));
770	
771	        Stmt body = SeqStmt::Flatten(in_let_statement);
772	        for (size_t i = 0; i < size; i++) {
773	          body = LetStmt(in_warp_local_vars[i], loads[i], body);
774	        }
775	        in_warp_seq.push_back(body);
776	      }
777	
778	      Stmt warp_body = SeqStmt::Flatten(in_warp_seq);
779	
780	      seq.emplace_back(IfThenElse(in_warp_cond, warp_body));
781	      seq.emplace_back(SyncThread(shared_scope));
782	    }
783	    return SeqStmt::Flatten(seq);
784	  }
785	  // Flatten the thread index.
786	  // Also return a warp number,
787	  PrimExpr FlattenThread(const std::vector<ThreadEntry> &tvec,
788	                         int *out_total_extent) {
789	    int &total_extent = *out_total_extent;
790	    total_extent = 1;
791	    if (tvec.empty()) {
792	      return make_zero(DataType::Int(32));
793	    }
794	
795	    PrimExpr ret;
796	    for (const ThreadEntry &e : tvec) {
797	      if (ret.defined()) {
798	        ret = ret + e.iv->var * total_extent;
799	      } else {
800	        ICHECK_EQ(total_extent, 1);
801	        ret = e.iv->var;
802	      }
803	      total_extent *= e.extent;
804	    }
805	    return ret;
806	  }
807	  // The local buffer index.
808	  PrimExpr BufIndex(PrimExpr reduce_index, const PrimExpr &group_index,
809	                    int reduce_extent) {
810	    if (!is_zero(group_index)) {
811	      return analyzer_.Simplify(group_index * reduce_extent + reduce_index);
812	    } else {
813	      return reduce_index;
814	    }
815	  }
816	  // sync thread op.
817	  static Stmt SyncThread(const std::string &sync) {
818	    return Evaluate(Call(DataType::Int(32), builtin::tvm_storage_sync(),
819	                         {StringImm(sync)}));
820	  }
821	
822	  // Emit warp shuffle  calls.
823	  PrimExpr WarpShuffle(const Op &op, const Optional<Buffer> &mask_buffer,
824	                       const PrimExpr &val, PrimExpr delta_or_lane) {
825	    Array<PrimExpr> indices = {0};
826	    PrimExpr mask;
827	    if (mask_buffer.defined()) {
828	      mask = BufferLoad(mask_buffer.value(), indices);
829	    } else {
830	      mask = IntImm(DataType::Int(32), 0);
831	    }
832	    PrimExpr width = IntImm(DataType::Int(32), warp_size_);
833	    Array<PrimExpr> args{mask, val, std::move(delta_or_lane), width, width};
834	    return Call(val.dtype(), op, args);
835	  }
836	
837	  // Check if we can use warp level reduction.
838	  //
839	  // Note: The ROCm backend will only have warp reductions for now.
840	  // Also, the warp/wavefront size differs (64 on rocm, 32 on cuda and metal).
841	  bool IsWarpReduction(const std::vector<DataType> &types, int group_extent,
842	                       int reduce_extent, int contiguous_reduce_extent) {
843	    if ((target_->kind->name != "cuda") && (target_->kind->name != "rocm") &&
844	        (target_->kind->name != "metal")) {
845	      return false;
846	    }
847	
848	    need_warp_shuffle_mask_ = target_->kind->name != "metal";
849	
850	    // rocm only supports 32 bit operands for shuffling at the moment
851	    if ((target_->kind->name == "rocm") &&
852	        (std::any_of(types.begin(), types.end(), [](DataType ty) {
853	          if (ty.is_fixed_length_vector())
854	            return ty.bits() * ty.lanes() != 32;
855	          return ty.bits() != 32;
856	        }))) {
857	      return false;
858	    }
859	
860	    // Supported types:
861	    // {u}int, {u}long, {u}long long, float, double, half/half2
862	    if (std::any_of(types.begin(), types.end(), [](DataType ty) {
863	          if (ty.is_float16())
864	            return ty.lanes() > 2;
865	          if (ty.is_fixed_length_vector())
866	            return true;
867	          return ty.bytes() < 4 || ty.bytes() > 8;
868	        })) {
869	      return false;
870	    }
871	    if (thread_extents_.empty()) {
872	      return false;
873	    }
874	
875	    // reduce region must be contiguous.
876	    if (contiguous_reduce_extent != reduce_extent) {
877	      return false;
878	    }
879	
880	    // whether reduce_extent and group_extent are valid for warp reduction.
881	    if (target_->kind->name == "rocm") {
882	      return reduce_extent == warp_size_;
883	    } else {
884	      if (reduce_extent == 1) {
885	        return false; // no need to warp reduce
886	      } else {
887	        bool is_subwarp_reduction = warp_size_ % reduce_extent == 0;
888	        bool is_multiwarp_reduction =
889	            max_num_threads_ != -1 &&
890	            max_num_threads_ <= warp_size_ * warp_size_ &&
891	            reduce_extent % warp_size_ == 0;
892	        if (is_subwarp_reduction || is_multiwarp_reduction) {
893	          return true;
894	        } else {
895	          return group_extent == 1 && reduce_extent <= warp_size_;
896	        }
897	      }
898	    }
899	  }
900	
901	  // The target.
902	  const TargetNode *target_ = nullptr;
903	  // The shared scope.
904	  String shared_scope = "shared";
905	  // The warp size of the device.
906	  int warp_size_{1};
907	  // The maximum number of threads of the device. "-1" denotes unknown.
908	  int max_num_threads_{-1};
909	  // A boolean indicating if the target supports warp-level masking.
910	  bool need_warp_shuffle_mask_{};
911	
912	  // surrounding scope of thread extent.
913	  std::vector<const AttrStmtNode *> thread_extents_;
914	  std::vector<const CommReducerNode *> reduce_combiner_;
915	  // The load remap
916	  std::unordered_map<const VarNode *, PrimExpr> load_remap_;
917	  // Allocate remap
918	  std::unordered_map<const VarNode *, Buffer> alloc_remap_;
919	  // BufferVar remap
920	  std::unordered_map<const VarNode *, Var> var_remap_;
921	  // Buffer remap
922	  std::unordered_map<const BufferNode *, Buffer> buf_remap_;
923	  // Internal analyzer
924	  arith::Analyzer analyzer_;
925	};
926	
927	namespace transform {
928	using namespace tir::transform;
929	
930	tvm::transform::Pass LowerThreadAllreduce() {
931	  auto pass_func = [](PrimFunc f, const IRModule &m, const PassContext &ctx) {
932	    AllocateCollector collector;
933	    collector(f->body);
934	    bool is_dynamic = collector.dyn_shmem_allocs_.size() > 1;
935	
936	    auto *n = f.CopyOnWrite();
937	    auto target = f->GetAttr<Target>(tvm::attr::kTarget);
938	    ICHECK(target.defined())
939	        << "LowerThreadAllreduce: Require the target attribute";
940	    const TargetNode *target_node = target.as<TargetNode>();
941	    ThreadAllreduceBuilder thread_all_reduce(target_node, is_dynamic);
942	    n->body = thread_all_reduce(n->body);
943	    return f;
944	  };
945	  return CreatePrimFuncPass(pass_func, 0, "tl.LowerThreadAllreduce", {});
946	}
947	
948	TVM_FFI_STATIC_INIT_BLOCK() {
949	  namespace refl = tvm::ffi::reflection;
950	  refl::GlobalDef().def("tl.transform.LowerThreadAllreduce",
951	                        LowerThreadAllreduce);
952	}
953	
954	} // namespace transform
955	} // namespace tl
956	} // namespace tvm
